from pathlib import Path
import sqlite3, pandas as pd, json
ROOT=Path(__file__).resolve().parents[1]; DB=ROOT/'indus_weave.db'; OUT=ROOT/'results/analytics'; OUT.mkdir(parents=True,exist_ok=True)
QUERIES={
'q01_headcount':'''WITH months(month_start,month_end) AS (VALUES ('2026-04-01','2026-04-30'),('2026-05-01','2026-05-31'),('2026-06-01','2026-06-30'),('2026-07-01','2026-07-31'),('2026-08-01','2026-08-31'),('2026-09-01','2026-09-30')) SELECT m.month_start,d.plant_name,d.department_name,COUNT(DISTINCT e.emp_id) headcount FROM months m JOIN dim_employee e ON e.valid_from<=m.month_end AND e.valid_to>=m.month_end JOIN dim_department d ON d.department_key=e.department_key JOIN staging_employee_entitlement se ON se.emp_id=e.emp_id WHERE e.hire_date<=m.month_end AND (e.separation_date='' OR e.separation_date IS NULL OR e.separation_date>m.month_end) GROUP BY m.month_start,d.plant_name,d.department_name ORDER BY m.month_start,d.plant_name,d.department_name''',
'q02_attrition':'''SELECT h.month_start,h.department_name,COUNT(DISTINCT s.emp_id) separations,(h.opening_headcount+h.closing_headcount)/2.0 average_headcount,ROUND(100.0*COUNT(DISTINCT s.emp_id)/NULLIF((h.opening_headcount+h.closing_headcount)/2.0,0),2) attrition_rate_pct FROM staging_monthly_headcount h LEFT JOIN staging_separations s ON s.department_name=h.department_name AND s.month_start=h.month_start GROUP BY h.month_start,h.department_name ORDER BY h.month_start,h.department_name''',
'q03_absenteeism':'''SELECT d.plant_name,substr(dt.full_date,1,7) month,SUM(a.status='Absent') absent_days,SUM(a.status IN ('Present','Absent','Missing Punch')) scheduled_workdays,ROUND(100.0*SUM(a.status='Absent')/NULLIF(SUM(a.status IN ('Present','Absent','Missing Punch')),0),2) absenteeism_pct FROM fact_attendance_daily a JOIN dim_date dt ON dt.date_key=a.date_key JOIN dim_employee e ON e.employee_key=a.employee_key JOIN dim_department d ON d.department_key=e.department_key GROUP BY d.plant_name,substr(dt.full_date,1,7) ORDER BY month,d.plant_name''',
'q04_late_arrivals':'''SELECT a.emp_id,e.employee_name,d.department_name,COUNT(*) late_arrival_days,SUM(a.late_minutes) total_late_minutes FROM fact_attendance_daily a JOIN dim_employee e ON e.employee_key=a.employee_key JOIN dim_department d ON d.department_key=e.department_key JOIN dim_date dt ON dt.date_key=a.date_key WHERE a.status='Present' AND a.late_minutes>0 AND dt.full_date BETWEEN '2026-04-01' AND '2026-09-30' GROUP BY a.emp_id,e.employee_name,d.department_name ORDER BY late_arrival_days DESC,total_late_minutes DESC LIMIT 10''',
'q05_overtime_reconciliation':'''SELECT month,department_name,ROUND(computed_hours,2) computed_hours,ROUND(approved_hours,2) approved_hours,ROUND(paid_hours,2) paid_hours,ROUND(paid_hours-computed_hours,2) paid_minus_computed_hours FROM staging_overtime_reconciliation ORDER BY month,department_name''',
'q06_paid_ot_exceeds_computed':'''SELECT month,department_name,computed_overtime_value computed_hours,paid_overtime_value paid_hours,ROUND(100.0*(paid_overtime_value-computed_overtime_value)/NULLIF(computed_overtime_value,0),2) excess_pct FROM staging_overtime_reconciliation WHERE computed_overtime_value>0 AND paid_overtime_value>computed_overtime_value*1.15 ORDER BY month,excess_pct DESC''',
'q07_paid_zero_attendance':'''WITH paid AS (SELECT emp_id,substr(month_start,1,7) month,SUM(amount) paid_amount FROM fact_payroll_line WHERE amount<>0 GROUP BY emp_id,substr(month_start,1,7)), att AS (SELECT a.emp_id,substr(d.full_date,1,7) month,SUM(a.status='Present') present_days FROM fact_attendance_daily a JOIN dim_date d ON d.date_key=a.date_key GROUP BY a.emp_id,substr(d.full_date,1,7)) SELECT p.emp_id,p.month,p.paid_amount,COALESCE(a.present_days,0) present_days FROM paid p LEFT JOIN att a ON a.emp_id=p.emp_id AND a.month=p.month WHERE COALESCE(a.present_days,0)=0 ORDER BY p.month,p.emp_id''',
'q08_paid_after_separation':'''SELECT p.emp_id,p.month_start,s.separation_date,p.pay_component,p.amount FROM fact_payroll_line p JOIN staging_separations s ON s.emp_id=p.emp_id WHERE date(p.month_start)>date(s.separation_date,'start of month') AND p.amount<>0 ORDER BY p.emp_id,p.month_start''',
'q09_payroll_cost_mom':'''WITH monthly AS (SELECT substr(month_start,1,7) month,department_key,emp_id,SUM(CASE WHEN upper(component_type)='EARNING' THEN amount ELSE 0 END) payroll_cost FROM fact_payroll_line GROUP BY substr(month_start,1,7),department_key,emp_id), dept AS (SELECT month,department_key,SUM(payroll_cost) total_payroll_cost,COUNT(DISTINCT emp_id) employees,SUM(payroll_cost)/NULLIF(COUNT(DISTINCT emp_id),0) cost_per_employee FROM monthly GROUP BY month,department_key) SELECT p.month,d.department_name,ROUND(p.total_payroll_cost,2) total_payroll_cost,p.employees,ROUND(p.cost_per_employee,2) cost_per_employee,ROUND(LAG(p.cost_per_employee) OVER(PARTITION BY p.department_key ORDER BY p.month),2) prior_month_cost_per_employee,ROUND(100.0*(p.cost_per_employee-LAG(p.cost_per_employee) OVER(PARTITION BY p.department_key ORDER BY p.month))/NULLIF(LAG(p.cost_per_employee) OVER(PARTITION BY p.department_key ORDER BY p.month),0),2) mom_change_pct FROM dept p JOIN dim_department d ON d.department_key=p.department_key ORDER BY p.month,d.department_name''',
'q10_annual_leave_overuse':'''WITH used AS (SELECT emp_id,COUNT(*) approved_annual_leave_days FROM fact_leave_day l JOIN dim_date d ON d.date_key=l.date_key WHERE lower(l.leave_type) IN ('annual','annual leave') AND d.full_date BETWEEN '2026-04-01' AND '2026-09-30' GROUP BY emp_id) SELECT u.emp_id,u.approved_annual_leave_days,e.annual_leave_entitlement_days FROM used u JOIN staging_employee_entitlement e ON e.emp_id=u.emp_id WHERE u.approved_annual_leave_days>e.annual_leave_entitlement_days ORDER BY u.approved_annual_leave_days DESC'''
}
def main():
 with sqlite3.connect(DB) as con:
  summary=[]
  for name,sql in QUERIES.items():
   try:
    df=pd.read_sql_query(sql,con); df.to_csv(OUT/f'{name}.csv',index=False); (ROOT/'analytics'/f'{name}.sql').write_text('-- Generated executable query. Run with SQLite against indus_weave.db.\n'+sql+';\n'); summary.append({'query':name,'status':'PASS','rows':len(df),'columns':len(df.columns)})
   except Exception as e: summary.append({'query':name,'status':'FAIL','error':str(e)}); print(name,'FAILED',e)
  pd.DataFrame(summary).to_csv(OUT/'query_test_results.csv',index=False)
  missing_punch_sql="""SELECT substr(d.full_date,1,7) month,dept.plant_name,dept.department_name,COUNT(*) missing_punch_days FROM fact_attendance_daily a JOIN dim_date d ON d.date_key=a.date_key JOIN dim_employee e ON e.employee_key=a.employee_key JOIN dim_department dept ON dept.department_key=e.department_key WHERE a.status='Missing Punch' GROUP BY month,dept.plant_name,dept.department_name ORDER BY month,dept.plant_name,dept.department_name"""
  pd.read_sql_query(missing_punch_sql,con).to_csv(OUT/'review_missing_punches.csv',index=False)
  (ROOT/'analytics'/'review_missing_punches.sql').write_text(
   '-- Supplemental evidence query for the CFO findings; not one of the ten scored questions.\\n'
   +missing_punch_sql+';\\n',encoding='utf-8')
  # dashboard aggregate data
  metrics={
   'employees':con.execute('SELECT COUNT(DISTINCT emp_id) FROM dim_employee').fetchone()[0],
   'attendance_records':con.execute('SELECT COUNT(*) FROM fact_attendance_daily').fetchone()[0],
   'present_days':con.execute("SELECT COUNT(*) FROM fact_attendance_daily WHERE status='Present'").fetchone()[0],
   'absent_days':con.execute("SELECT COUNT(*) FROM fact_attendance_daily WHERE status='Absent'").fetchone()[0],
   'missing_punch_days':con.execute("SELECT COUNT(*) FROM fact_attendance_daily WHERE status='Missing Punch'").fetchone()[0],
   'late_minutes':con.execute('SELECT COALESCE(SUM(late_minutes),0) FROM fact_attendance_daily').fetchone()[0],
   'computed_overtime_hours':round(con.execute('SELECT COALESCE(SUM(computed_overtime_hours),0) FROM fact_attendance_daily').fetchone()[0],2),
   'payroll_earnings':round(con.execute("SELECT COALESCE(SUM(amount),0) FROM fact_payroll_line WHERE upper(component_type)='EARNING'").fetchone()[0],2),
   'approved_ot_hours':round(con.execute('SELECT COALESCE(SUM(approved_hours),0) FROM fact_overtime_approved').fetchone()[0],2),
   'paid_ot_hours':round(con.execute("SELECT COALESCE(SUM(units),0) FROM fact_payroll_line WHERE upper(pay_component)='OVERTIME'").fetchone()[0],2)}
  bymonth=pd.read_sql_query("SELECT substr(d.full_date,1,7) month,SUM(a.status='Present') present,SUM(a.status='Absent') absent,SUM(a.status='Missing Punch') missing,SUM(a.late_minutes) late_minutes,ROUND(SUM(a.computed_overtime_hours),1) overtime FROM fact_attendance_daily a JOIN dim_date d ON d.date_key=a.date_key GROUP BY month ORDER BY month",con).to_dict('records')
  plants=pd.read_sql_query("SELECT d.plant_name plant,COUNT(*) records,SUM(a.status='Present') present,SUM(a.status='Absent') absent,SUM(a.status='Missing Punch') missing FROM fact_attendance_daily a JOIN dim_employee e ON e.employee_key=a.employee_key JOIN dim_department d ON d.department_key=e.department_key GROUP BY d.plant_name ORDER BY records DESC",con).to_dict('records')
  depts=pd.read_sql_query("SELECT d.department_name department,ROUND(SUM(CASE WHEN upper(p.component_type)='EARNING' THEN p.amount ELSE 0 END),0) payroll FROM fact_payroll_line p JOIN dim_department d ON d.department_key=p.department_key GROUP BY d.department_name ORDER BY payroll DESC LIMIT 8",con).to_dict('records')
  checks=pd.read_sql_query('SELECT check_name,table_name,failed_rows,status,details FROM dq_results',con).to_dict('records')
  dashboard={'metrics':metrics,'monthly':bymonth,'plants':plants,'payroll_departments':depts,'dq':checks,'query_tests':summary}
  (OUT/'dashboard_data.json').write_text(json.dumps(dashboard,indent=2,default=str))
  print(pd.DataFrame(summary).to_string(index=False)); print('Dashboard metrics',metrics)
if __name__=='__main__':main()
